renderer_source_audit.renderAadrgDetail:
function renderAadrgDetail(payload) {
  const detail = payload.detail; const fragment = document.createDocumentFragment(); fragment.append(makeMetaGrid([['AADRG', detail.aadrg], ['질병군명', detail.group_name], ['상위 ADRG', detail.adrg], ['MDC', mdcDisplayText(detail.mdc, detail.mdc_name)], ['질병군 분류', makeClassificationBadgeGroup([detail.classification_code || detail.classification_display_label])]], 'detail-overview-grid'));
  fragment.append(renderUserConditionSummary(detail), renderUserConditionTables(detail)); const codes = makeSection('관련 코드', '이 AADRG에 직접 연결되는 코드입니다.', { open: false, count: (detail.related_code_summaries ?? []).length }); codes.append(makeSummaryList(detail.related_code_summaries)); const rdrg = makeSection('파생 RDRG', '중증도 분기를 포함한 최종 RDRG입니다.', { open: false, count: (detail.rdrg_records ?? []).length }); rdrg.append(makeSummaryList(detail.rdrg_records)); fragment.append(codes, rdrg); return fragment;
}

renderer_source_audit.directConditionTables:
function directConditionTables(detail) {
  const coverage = Ui.userConditionCoverage(detail);
  if (
    coverage.status !== 'NO_EXPLICIT_CONDITION'
    || detail?.condition_ast
    || coverage.table_count
  ) {
    return [];
  }

  const adrg = String(detail?.adrg ?? '').trim();
  const sourceIds = Ui.uniqueStrings(detail?.source_logical_table_ids ?? []);
  if (!adrg || sourceIds.length !== 1) return [];

  const tableId = sourceIds[0];
  if (!directConditionLocalTablePattern(adrg).test(tableId)) return [];

  const summaryMap = Ui.tableSummaryMap(detail);
  const summary = summaryMap.get(tableId);
  if (!summary) return [];

  const summaryData = summary?.summary ?? summary ?? {};
  const codeCount = Number(summaryData.code_count ?? 0);
  if (codeCount <= 0) return [];

  const sourceLabel = tableUserLabel(summary);
  const hasOfficialRoleLabel = DIRECT_CONDITION_ROLE_PATTERN.test(sourceLabel);
  const label = hasOfficialRoleLabel
    ? sourceLabel
    : DIRECT_CONDITION_NEUTRAL_LABEL;

  return [{
    tableId,
    summary,
    label,
    codeCount,
    hasOfficialRoleLabel,
  }];
}
